import { useMemo } from "react";
import { Audio } from "@remotion/media";
import { createTikTokStyleCaptions, type Caption, type TikTokPage } from "@remotion/captions";
import { measureText } from "@remotion/layout-utils";
import {
  AbsoluteFill,
  Composition,
  Sequence,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
  type CalculateMetadataFunction,
} from "remotion";

const FPS = 30;
const FONT = "DejaVu Sans";
const TITLES = ["Свежий\nвоздух", "Вода и\nдыхание", "Начните\nс главного"];

type Timing = {
  version: number;
  format: "wav" | "mp3";
  durationMs: number;
  text: string;
  words: { text: string; startMs: number; endMs: number }[];
};

type Scene = {
  timing: Timing;
  audioPath: string;
  from: number;
  durationInFrames: number;
  title: string;
  index: number;
  pages: TikTokPage[];
};

type Props = { scenes: Scene[] };

const loadTiming = async (index: number, signal: AbortSignal) => {
  const base = `voice/scene-${String(index + 1).padStart(2, "0")}`;
  for (const stem of [`${base}-piper-v2`, `${base}-piper`, base]) {
    const response = await fetch(staticFile(`${stem}.words.json`), { signal });
    if (response.status === 404) continue;
    if (!response.ok) throw new Error(`Timing request failed: ${response.status}`);
    const timing = (await response.json()) as Timing;
    if (!Number.isFinite(timing.durationMs) || timing.durationMs <= 0) {
      throw new Error(`Invalid timing duration: ${stem}`);
    }
    if (timing.format !== "wav" && timing.format !== "mp3") {
      throw new Error(`Unsupported audio format: ${stem}`);
    }
    return { timing, audioPath: `${stem}.${timing.format}` };
  }
  throw new Error(`No timing JSON found for ${base}`);
};

export const calculateMetadata: CalculateMetadataFunction<Props> = async ({ abortSignal }) => {
  const loaded = await Promise.all(TITLES.map((_, index) => loadTiming(index, abortSignal)));
  let from = 0;
  const scenes = loaded.map(({ timing, audioPath }, index): Scene => {
    const durationInFrames = Math.ceil(10 + timing.durationMs / 1000 * FPS + 0.5 * FPS);
    const offsetMs = 10 / FPS * 1000;
    const captions: Caption[] = timing.words.map((word, wordIndex) => ({
      text: `${wordIndex === 0 ? "" : " "}${word.text}`,
      startMs: word.startMs + offsetMs,
      endMs: word.endMs + offsetMs,
      timestampMs: (word.startMs + word.endMs) / 2 + offsetMs,
      confidence: null,
    }));
    const { pages } = createTikTokStyleCaptions({
      captions,
      combineTokensWithinMilliseconds: 1000,
      breakOnSilenceAfterMilliseconds: 300,
    });
    const scene = { timing, audioPath, from, durationInFrames, title: TITLES[index], index, pages };
    from += durationInFrames;
    return scene;
  });
  return { durationInFrames: from, fps: FPS, props: { scenes } };
};

const widthOf = (text: string, fontSize: number, fontWeight: string) => measureText({
  text,
  fontFamily: FONT,
  fontSize,
  fontWeight,
  letterSpacing: "0px",
}).width;

export const layoutPage = (page: TikTokPage) => {
  let currentLine = "";
  let lines = 1;
  const lineWidths: number[] = [];
  const tokens = page.tokens.map((token) => {
    let text = token.text;
    if (widthOf(currentLine + text, 80, "400") > 1536) {
      lineWidths.push(widthOf(currentLine, 80, "400"));
      text = `\n${text.trimStart()}`;
      currentLine = text.trimStart();
      lines += 1;
    } else {
      currentLine += text;
    }
    if (lines > 2 || widthOf(currentLine, 80, "400") > 1536) {
      throw new Error(`Caption requires re-pagination before rendering: ${page.text}`);
    }
    return { ...token, text };
  });
  lineWidths.push(widthOf(currentLine, 80, "400"));
  return { ...page, tokens, lines, lineWidths };
};

const Captions = ({ pages }: { pages: TikTokPage[] }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const timeMs = frame / fps * 1000;
  const laidOut = useMemo(() => pages.map(layoutPage), [pages]);
  const page = laidOut.find((candidate) => candidate.startMs <= timeMs && timeMs < candidate.startMs + candidate.durationMs);
  if (!page) return null;
  return (
    <div style={{
      position: "absolute",
      left: 160,
      right: 160,
      bottom: 190,
      textAlign: "center",
      fontSize: 80,
      fontWeight: 400,
      lineHeight: 1.22,
      whiteSpace: "pre",
    }}>
      <div style={{ display: "inline-block", padding: "18px 32px", borderRadius: 24, backgroundColor: "#183831", color: "#FFFFFF" }}>
        {page.tokens.map((token, index) => (
          <span key={index} style={{
            opacity: timeMs >= token.fromMs ? 1 : 0,
            color: token.fromMs <= timeMs && timeMs < token.toMs ? "#F7D48E" : "#FFFFFF",
          }}>{token.text}</span>
        ))}
      </div>
    </div>
  );
};

const Illustration = ({ index }: { index: number }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const drift = Math.sin(frame / fps * Math.PI / 3) * 5;
  return (
    <svg width={500} height={400} viewBox="0 0 500 400" style={{ position: "absolute", left: 1250, top: 200 }}>
      <ellipse cx="250" cy="360" rx="190" ry="18" fill="#DCE5DA" />
      {index === 0 ? (
        <>
          <rect x="80" y="35" width="310" height="295" rx="16" fill="#E5F0EA" stroke="#345E51" strokeWidth="9" />
          <circle cx="300" cy="118" r="45" fill="#EBCB8E" />
          <path d="M85 268 Q170 175 245 250 T385 245 V325 H85Z" fill="#AECAB7" />
          <path d="M236 40 V324 M84 180 H386" stroke="#345E51" strokeWidth="9" />
          <path d="M236 40 L365 75 V293 L236 324Z" fill="#F8FBF5" fillOpacity="0.78" stroke="#345E51" strokeWidth="8" />
          <path d={`M25 ${242 + drift} Q82 ${219 + drift} 141 ${242 + drift} M17 ${278 + drift} Q85 ${252 + drift} 153 ${278 + drift}`} fill="none" stroke="#70998B" strokeWidth="8" strokeLinecap="round" />
          <path d="M58 335 H413" stroke="#345E51" strokeWidth="13" strokeLinecap="round" />
        </>
      ) : index === 1 ? (
        <>
          <circle cx="250" cy="182" r="155" fill="#E5EEDF" />
          <path d="M133 90 H342 L320 322 Q318 338 300 338 H176 Q158 338 156 322Z" fill="#FAFCF6" stroke="#345E51" strokeWidth="8" />
          <path d={`M147 191 Q193 ${178 + drift} 237 191 T328 191 L316 318 Q315 327 300 327 H176 Q166 327 165 317Z`} fill="#9AC6C1" />
          <path d="M174 113 L183 170" stroke="#FFFFFF" strokeWidth="10" strokeLinecap="round" />
          <path d={`M371 ${132 + drift} Q420 ${156 + drift} 373 ${180 + drift} M373 ${205 + drift} Q425 ${229 + drift} 373 ${253 + drift}`} fill="none" stroke="#70998B" strokeWidth="8" strokeLinecap="round" />
        </>
      ) : (
        <>
          <circle cx="250" cy="183" r="158" fill="#E5EEDF" />
          <rect x="107" y="54" width="281" height="286" rx="21" fill="#FAFCF6" stroke="#345E51" strokeWidth="8" />
          <rect x="196" y="36" width="103" height="34" rx="12" fill="#345E51" />
          <rect x="144" y="111" width="52" height="52" rx="10" fill="#DCEBDC" />
          <path d="M156 137 L168 149 L188 123" stroke="#345E51" strokeWidth="8" fill="none" strokeLinecap="round" strokeLinejoin="round" />
          <path d="M224 133 H344" stroke="#70998B" strokeWidth="10" strokeLinecap="round" />
          <path d="M147 208 H344 M147 265 H302" stroke="#CDD9CC" strokeWidth="10" strokeLinecap="round" />
          <circle cx="392" cy={299 + drift} r="27" fill="#EBCB8E" />
        </>
      )}
    </svg>
  );
};

const SceneContent = ({ scene }: { scene: Scene }) => (
  <AbsoluteFill style={{ backgroundColor: "#F4F3E9", color: "#183831", fontFamily: FONT }}>
    <div style={{ position: "absolute", left: 160, top: 210, width: 980, fontSize: 160, fontWeight: 700, lineHeight: 1.12, whiteSpace: "pre" }}>
      {scene.title}
    </div>
    <Illustration index={scene.index} />
    <Sequence from={10} layout="none">
      <Audio src={staticFile(scene.audioPath)} />
    </Sequence>
    <Captions pages={scene.pages} />
  </AbsoluteFill>
);

export const Main = ({ scenes }: Props) => (
  <AbsoluteFill>
    {scenes.map((scene) => (
      <Sequence key={scene.index} name={scene.title.replace("\n", " ")} from={scene.from} durationInFrames={scene.durationInFrames}>
        <SceneContent scene={scene} />
      </Sequence>
    ))}
  </AbsoluteFill>
);

export const RemotionRoot = () => (
  <Composition
    id="Main"
    component={Main}
    width={1920}
    height={1080}
    fps={FPS}
    durationInFrames={1}
    defaultProps={{ scenes: [] }}
    calculateMetadata={calculateMetadata}
  />
);
